// EmbedContainer.tsx
//
// Generated by rjui_tools `rjui init`. Container for the `Embed` view type.
// Hosts another screen as a region of the parent layout; the embedded screen
// owns its own ViewModel via React hook scoping (hooks called inside the
// embedded component are isolated per render position).
//
// v1 (P1): delegate navigation only, no params/events bridging. params/events
// are wired in P2; isolated navigation in P3.
//
// See jsonui-cli/docs/plans/2026-05-11-embed-feature.md.

import React from 'react';

export type EmbedNavigationMode = 'delegate' | 'isolated';

export interface EmbedContainerProps {
  /** Unique id of this embed slot within the parent layout. */
  embedId: string;
  /** Name of the embedded screen. */
  screen: string;
  /** How navigation calls from the embedded screen are wired. */
  navigationMode?: EmbedNavigationMode;
  /** Optional className applied to the container div. */
  className?: string;
  /** The embedded screen component. */
  children: React.ReactNode;
}

export const EmbedContainer: React.FC<EmbedContainerProps> = ({
  embedId,
  screen,
  navigationMode = 'delegate',
  className,
  children,
}) => {
  return (
    <div
      data-embed-id={embedId}
      data-embed-screen={screen}
      data-embed-navigation-mode={navigationMode}
      className={className}
    >
      {children}
    </div>
  );
};

export default EmbedContainer;
